import{_ as a,c as i,o as n,b0 as e}from"./chunks/framework.CLL9SSSf.js";const l="/linux-driver-docs/assets/image-20250322094204703.Crs5a9C6.png",t="/linux-driver-docs/assets/image-20250322095959293.BEGhhY3G.png",b=JSON.parse('{"title":"LV070-工作队列简介","description":null,"frontmatter":{"title":"LV070-工作队列简介","date":"2026-01-20T09:34:12.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/drv-base/irq/126d2d42e2e4393a6a492406","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-20T09:34:12.915Z","fulluuid":"a6a4924061cd4b3fb43fa8a0d7007890","useduuid":"a6a492406"}},"headers":[],"relativePath":"sdoc/drv-base/irq/126d2d42e2e4393a6a492406.md","filePath":"sdoc/05-设备驱动基础/45-中断/LV070-工作队列简介.md","lastUpdated":1769002717000}'),r={name:"sdoc/drv-base/irq/126d2d42e2e4393a6a492406.md"};function p(h,s,k,d,o,c){return n(),i("div",null,[...s[0]||(s[0]=[e('<h1 id="lv070-工作队列简介" tabindex="-1">LV070-工作队列简介 <a class="header-anchor" href="#lv070-工作队列简介" aria-label="Permalink to &quot;LV070-工作队列简介&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>在中断下半部的执行过程中，虽然是开中断的，期间可以处理各类中断。但是毕竟整个中断的处理还没走完，这期间 APP 是无法执行的。假设下半部要执行 1、 2 分钟，在这 1、 2 分钟里 APP 都是无法响应的。</p><p>这谁受得了？所以，如果中断要做的事情实在太耗时，那就不能用软件中断来做，而应该用内核线程来做：在中断上半部唤醒内核线程。内核线程和 APP 都一样竞争执行， APP 有机会执行，系统不会卡顿。这个内核线程是系统帮我们创建的，一般是 kworker 线程，内核中有很多这样的线程：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kworker</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+l+`" alt="image-20250322094204703"><p>总的来说，下半部要做的事情太多并且很复杂，我们就可以考虑使用工作队列。接下来就来了解一下吧。</p><h2 id="二、工作队列简介" tabindex="-1">二、工作队列简介 <a class="header-anchor" href="#二、工作队列简介" aria-label="Permalink to &quot;二、工作队列简介&quot;">​</a></h2><h3 id="_1-什么是工作队列" tabindex="-1">1. 什么是工作队列 <a class="header-anchor" href="#_1-什么是工作队列" aria-label="Permalink to &quot;1. 什么是工作队列&quot;">​</a></h3><p>工作队列是实现中断下半部分的机制之一， 是一种用于管理任务的数据结构或机制。 它通常用于多线程， 多进程或分布式系统中， 用于协调和分配待处理的任务给可用的工作线程或工作进程。</p><p>工作队列（work queue）是另外一种将工作推后执行的形式，它和前面讨论的 tasklet 有所不同。工作队列可以把工作推后，交由一个内核线程去执行，也就是说，这个下半部分可以在进程上下文中执行。这样，通过工作队列执行的代码能占尽进程上下文的所有优势。最重要的就是 <strong>工作队列允许被重新调度甚至是睡眠。</strong></p><p>那么，什么情况下使用工作队列，什么情况下使用 tasklet。<strong>如果推后执行的任务需要睡眠，那么就选择工作队列；如果推后执行的任务不需要睡眠，那么就选择 tasklet</strong>。另外，<strong>如果需要用一个可以重新调度的实体来执行我们的下半部处理，也应该使用工作队列</strong>。它是唯一能在进程上下文运行的下半部实现的机制，也只有它才可以睡眠。这意味着在需要获得大量的内存时、在需要获取信号量时，在需要执行阻塞式的 I/O 操作时，它都会非常有用。如果不需要用一个内核线程来推后执行工作，那么就考虑使用 tasklet。</p><p>但是多个工作(函数)是在某个内核线程中依序执行的，前面函数执行很慢，就会影响到后面的函数。在多 CPU 的系统下，一个工作队列可以有多个内核线程，可以在一定程度上缓解这个问题。</p><h3 id="_2-基本原理" tabindex="-1">2. 基本原理 <a class="header-anchor" href="#_2-基本原理" aria-label="Permalink to &quot;2. 基本原理&quot;">​</a></h3><p>工作队列的基本原理是将需要执行的任务按顺序排列在队列中， 并提供一组工作线程或者工作进程来处理队列中的任务。 当有新的任务到达时， 它们会被添加到队列的末尾， 工作线程或工作进程从队列的头部获取任务， 并执行相应的处理操作。</p><p>工作队列将工作推后以后， 会交给内核线程去执行。 Linux 在启动过程中会创建一个工作者内核线程， 这个线程创建以后处于 sleep 状态。 当有工作需要处理的时候， 会唤醒这个线程去处理工作。</p><p>在内核中，我们并不需要自己去创建线程，可以使用“ 工作队列 ” (workqueue)。内核初始化工作队列时，就为它创建了内核线程。以后我们要使用“工作队列”，只需要把“工作”放入“工作队列中”，对应的内核线程就会取出“工作”，执行里面的函数。</p><p>在 2.xx 的内核中，工作队列的内部机制比较简单；在现在 4.x 的内核中，工作队列的内部机制做得复杂无比，但是用法是一样的。</p><h3 id="_3-工作队列的类型" tabindex="-1">3. 工作队列的类型 <a class="header-anchor" href="#_3-工作队列的类型" aria-label="Permalink to &quot;3. 工作队列的类型&quot;">​</a></h3><p>在内核中， 工作队列包括共享工作队列和自定义工作队列这两种类型。 这两种类型的工作队列具有不同的特点和用途。</p><ul><li><strong>共享队列</strong> 是由内核管理的全局工作队列， 用于处理内核中一些系统级任务。 共享工作队列是内核中一个默认工作队列， 可以由多个内核组件和驱动程序共享使用。</li><li><strong>自定义工作队列</strong> 是由内核或驱动程序创建的特定工作队列， 用于处理特定的任务。 自定义工作队列通常与特定的内核模块或驱动程序相关联， 用于执行该模块或驱动程序相关的任务。</li></ul><h2 id="三、怎么描述" tabindex="-1">三、怎么描述？ <a class="header-anchor" href="#三、怎么描述" aria-label="Permalink to &quot;三、怎么描述？&quot;">​</a></h2><h3 id="_1-工作" tabindex="-1">1. 工作 <a class="header-anchor" href="#_1-工作" aria-label="Permalink to &quot;1. 工作&quot;">​</a></h3><p>我们把推后执行的任务叫做工作（work），在 Linux 内核中， 使用 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/workqueue.h#L102" target="_blank" rel="noreferrer">work_struct</a> 结构体表示一个工作项：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> work_struct {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	atomic_long_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list_head entry;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 连接所有工作的链表</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	work_func_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> func;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       // 要执行的函数</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CONFIG_LOCKDEP</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lockdep_map lockdep_map;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这些结构被连接成链表。当一个工作者线程被唤醒时，它会执行它的链表上的所有工作。工作被执行完毕，它就将相应的 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/include/linux/workqueue.h#L102" target="_blank" rel="noreferrer">work_struct</a> 对象从链表上移去。当链表上不再有对象的时候，它就会继续休眠。</p><h3 id="_2-工作队列" tabindex="-1">2. 工作队列 <a class="header-anchor" href="#_2-工作队列" aria-label="Permalink to &quot;2. 工作队列&quot;">​</a></h3><p>上面说的工作以队列结构组织成工作队列（workqueue），工作队列使用 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/kernel/workqueue.c#L237" target="_blank" rel="noreferrer">workqueue_struct</a> 结构体表示：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> workqueue_struct {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list_head	pwqs;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">		/* WR: all pwqs of this wq */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list_head	list;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">		/* PR: list of all workqueues */</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	//......</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_3-工作者线程" tabindex="-1">3. 工作者线程 <a class="header-anchor" href="#_3-工作者线程" aria-label="Permalink to &quot;3. 工作者线程&quot;">​</a></h3><p>工作有了，工作队列有了，那谁来处理工作？Linux 内核使用工作者线程(worker thread)来处理工作队列中的各个工作，使用 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/kernel/workqueue_internal.h#L24" target="_blank" rel="noreferrer">struct worker</a> 结构体表示工作者线程</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> worker {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	/* on idle list while idle, on busy hash table while busy */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	union</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list_head	entry;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	/* L: while idle */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hlist_node	hentry;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	/* L: while busy */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	//......</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	/* used only by rescuers to point to the target workqueue */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> workqueue_struct	</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rescue_wq;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">	/* I: the workqueue to rescue */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>每个 worker 都有一个工作队列，工作者线程处理自己工作队列中的所有工作。</p><h3 id="_4-总结" tabindex="-1">4. 总结 <a class="header-anchor" href="#_4-总结" aria-label="Permalink to &quot;4. 总结&quot;">​</a></h3><p>在实际的驱动开发中，我们只需要定义工作(work_struct)即可，关于工作队列和工作者线程我们基本不用去管。如下图，流水线相当于工作队列， 流水线上一个个等待处理的物料相当于一个个工作。 机器相当于内核线程或进程。</p><img src="`+t+'" alt="image-20250322095959293"><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/myarrow/article/details/9287169" target="_blank" rel="noreferrer">中断处理下半部机制-CSDN 博客</a></p><p><a href="https://blog.csdn.net/tiangwan2011/article/details/7254806" target="_blank" rel="noreferrer">软中断（softirq）机制_软中断机制-CSDN 博客</a></p></blockquote>',37)])])}const g=a(r,[["render",p]]);export{b as __pageData,g as default};
